package authn_test

import (
	"crypto/rand"
	"crypto/rsa"
	"testing"

	"github.com/egdaemon/eg/authn"
	"github.com/stretchr/testify/require"
	"golang.org/x/crypto/ssh"
	"golang.org/x/oauth2"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestOAuth2SSHConfig(t *testing.T) {
	t.Run("fills config values", func(t *testing.T) {
		priv, err := rsa.GenerateKey(rand.Reader, 2048)
		require.NoError(t, err)
		signer, err := ssh.NewSignerFromKey(priv)
		require.NoError(t, err)
		endpoint := oauth2.Endpoint{
			AuthURL:  "https://a.example.test/authorize",
			TokenURL: "https://a.example.test/token",
		}
		got := authn.OAuth2SSHConfig(signer, "secret", endpoint)
		require.Equal(t, ssh.FingerprintSHA256(signer.PublicKey()), got.ClientID)
		require.Equal(t, "secret", got.ClientSecret)
		require.Equal(t, endpoint, got.Endpoint)
	})
	t.Run("empty otp", func(t *testing.T) {
		priv, err := rsa.GenerateKey(rand.Reader, 2048)
		require.NoError(t, err)
		signer, err := ssh.NewSignerFromKey(priv)
		require.NoError(t, err)
		endpoint := oauth2.Endpoint{
			AuthURL:  "https://b.example.test/authorize",
			TokenURL: "https://b.example.test/token",
		}
		got := authn.OAuth2SSHConfig(signer, "", endpoint)
		require.Equal(t, ssh.FingerprintSHA256(signer.PublicKey()), got.ClientID)
		require.Empty(t, got.ClientSecret)
		require.Equal(t, endpoint, got.Endpoint)
	})
}
